// 高校受験 社会（歴史：鎌倉〜江戸前期 30 単元）の「動く図解スライド」。
// 「なぜ？」の連鎖で、7枚以上。単元の節（section）ごとに 1 枚の図解をひもづける。
import type { DiagramElement, DiagramFigure } from './figures';
import { C, FILL, bx, lb, ar, ln, ci, show, fresh } from './diagram-kit';

type Col = [string, string];
const BLUE: Col = [C.blue, FILL.blue];
const GREEN: Col = [C.green, FILL.green];
const RED: Col = [C.red, FILL.red];
const MAIN: Col = [C.main, FILL.warm];
const PURPLE: Col = [C.purple, FILL.purple];
const GRAY: Col = [C.gray, FILL.gray];
const YELLOW: Col = [C.main, FILL.yellow];

const B = (x: number, y: number, w: number, h: number, t?: string, c: Col = MAIN, size = 11): DiagramElement => bx(x, y, w, h, t, c[0], c[1], size);

// 下の説明帯（1〜3行）
const cap = (t: string, c: Col = BLUE, size = 12): DiagramElement => {
  const n = t.split('\n').length;
  return bx(14, 164, 292, 14 + 15 * n, t, c[0], c[1], size);
};
// 1枚＝まっさらな図＋下の帯
const S = (note: string, top: DiagramElement[], capText: string, c: Col = BLUE, size = 12) => ({ note, add: fresh(...top, cap(capText, c, size)) });

// 横一列の箱（矢印つき）。items は [文字, 色]
const R = (items: [string, Col][], y: number, h = 40, size = 11, x0 = 8, x1 = 312, gap = 14): DiagramElement[] => {
  const n = items.length;
  const w = (x1 - x0 - gap * (n - 1)) / n;
  const out: DiagramElement[] = [];
  items.forEach(([t, c], i) => {
    const x = x0 + i * (w + gap);
    if (i > 0) out.push(ar(x - gap + 1, y + h / 2, x - 1, y + h / 2, c[0]));
    out.push(B(x, y, w, h, t, c, size));
  });
  return out;
};
// 横一列の箱（矢印なし）
const G = (items: [string, Col][], y: number, h = 40, size = 11, x0 = 8, x1 = 312, gap = 6): DiagramElement[] => {
  const n = items.length;
  const w = (x1 - x0 - gap * (n - 1)) / n;
  return items.map(([t, c], i) => B(x0 + i * (w + gap), y, w, h, t, c, size));
};
// 縦に並べた箱（矢印つき）
const V = (items: [string, Col][], x: number, w: number, y0: number, h = 28, gap = 12, size = 11): DiagramElement[] => {
  const out: DiagramElement[] = [];
  items.forEach(([t, c], i) => {
    const y = y0 + i * (h + gap);
    if (i > 0) out.push(ar(x + w / 2, y - gap + 1, x + w / 2, y - 1, c[0]));
    out.push(B(x, y, w, h, t, c, size));
  });
  return out;
};
// 年表：線の上に年、下に出来事
const T = (items: [string, string, Col?][], y: number, size = 10, h = 36): DiagramElement[] => {
  const n = items.length;
  const x0 = 28;
  const x1 = 292;
  const w = Math.min(84, 300 / n - 4);
  const out: DiagramElement[] = [ln(8, y, 312, y, C.gray, false, 2)];
  items.forEach(([yr, ev, col], i) => {
    const c = col ?? MAIN;
    const x = n === 1 ? 160 : x0 + ((x1 - x0) * i) / (n - 1);
    out.push(ci(x, y, 5, undefined, c[0], c[1]));
    out.push(lb(x, y - 13, yr, size + 1, c[0], 'middle', true));
    out.push(B(Math.max(2, Math.min(318 - w, x - w / 2)), y + 10, w, h, ev, c, size));
  });
  return out;
};
// 「なぜ？」の問いかけ（上部の見出し）
const Q = (t: string, y = 14, size = 12): DiagramElement => lb(160, y, t, size, C.red, 'middle', true);
const L = (x: number, y: number, t: string, size = 11, c: string = C.ink, anchor: 'start' | 'middle' | 'end' = 'middle'): DiagramElement => lb(x, y, t, size, c, anchor, true);

