// ───────── s234 豊臣秀吉③：刀狩と兵農分離（節0：刀狩令の内容とねらい） ─────────
const s234 = show([
  S('1588年、秀吉は刀狩令（かたながりれい）を出しました。条文の要旨は三つです。①百姓が刀・脇差（わきざし）・弓・やり・鉄砲などの武具を持つことを禁じる。②取り上げた武具は、京都の方広寺の大仏の釘（くぎ）やかすがいにする。③百姓は農具だけを持ち、耕作に専念すれば子孫まで無事に暮らせる。',
    [B(10, 14, 300, 40, '① 百姓が刀・弓・やり・鉄砲を持つことを禁止', RED, 11), B(10, 60, 300, 40, '② 集めた武具は方広寺の大仏の釘にする', BLUE, 11), B(10, 106, 300, 40, '③ 農具だけ持って耕作に専念すれば安心', GREEN, 11)], '1588年 刀狩令の三つの内容', RED),
  S('❓表向きの理由は何でしょう。→ 「集めた武器で大仏の釘をつくる。だから百姓はこの世だけでなく、あの世でも救われる」というものです。',
    [Q('表向きの理由は？'), ...R([['取り上げた\n武具', GRAY], ['大仏の釘・\nかすがい', BLUE], ['あの世でも\n救われる', GREEN]], 34, 50, 11)], '表向きは「大仏のため」', BLUE),
  S('❓では、本当のねらいは何でしょう。→ 三つあります。一揆を防ぐこと、年貢を確保すること、身分を固定することです。',
    [Q('本当のねらいは？'), B(10, 28, 300, 30, '一揆を防ぐ', RED, 13), B(10, 64, 300, 30, '年貢の確保（耕作に専念させる）', GREEN, 13), B(10, 100, 300, 30, '身分の固定', BLUE, 13), L(160, 146, '武器を持つ者＝武士／耕す者＝百姓', 11, C.ink)], '本当のねらいは三つ', RED),
  S('❓どうして一揆を防げるのでしょう。→ 戦国時代には土一揆や一向一揆など、武装した農民が大名に対抗する例が多くありました。武器を取り上げれば、大規模な武力抵抗は難しくなります。',
    [Q('なぜ一揆を防げる？'), B(10, 28, 142, 50, '戦国時代\n武装した農民\n（土一揆・一向一揆）', GRAY, 11), B(168, 28, 142, 50, '刀狩\n武器を取り上げる', RED, 12), ar(152, 52, 166, 52, C.main), L(160, 106, '大規模な武力抵抗は難しくなる', 12, C.ink)], '武器を取り上げて武力抵抗をおさえた', RED),
  S('❓なぜ「大仏の釘」と書いたのでしょう。→ 武器を差し出すことに宗教的な意味を持たせて、反発をやわらげるための口実だったからです。資料問題では、この一文について「なぜこう書いたのか」と問われることがあります。',
    [Q('なぜ「大仏の釘」と書いた？'), B(10, 28, 300, 34, '武器を差し出すことに宗教的な意味をもたせる', BLUE, 11), ar(160, 64, 160, 82, C.main), B(30, 84, 260, 30, '百姓の反発をやわらげる口実', GREEN, 12)], '反発をやわらげるための口実', BLUE),
  S('注意です。刀狩は「武士から武器を取り上げた」のではありません。取り上げられたのは百姓です。主語を取りちがえないようにしましょう。',
    [B(10, 22, 142, 50, '取り上げられた人\n百姓', RED, 13), B(168, 22, 142, 50, '武士は\n武器を持ったまま', GRAY, 12), L(160, 98, '主語は「百姓」', 14, C.red), L(160, 122, '武器を持てるのは武士だけ', 12, C.ink)], '刀狩の対象は百姓', RED),
  S('まとめです。刀狩と太閤検地で、武器を持つ武士と、耕す百姓の身分がはっきり分かれました（兵農分離）。1591年の身分統制令で身分の移動も禁じられ、江戸時代の身分制度の土台になりました。',
    [...R([['刀狩\n百姓の武器なし', RED], ['兵農分離\n武士と百姓', BLUE], ['江戸時代の\n身分制度の土台', GREEN]], 30, 54, 10), L(160, 108, '1591年 身分統制令 ＝ 身分の移動を禁止', 11, C.gray)], '刀狩 → 兵農分離 → 身分制度の土台', MAIN),
], '刀狩令の内容とねらい');

