// ───────── s248 年貢のしくみと百姓一揆（節0：年貢のしくみ） ─────────
const bar = (y: number, mine: number): DiagramElement[] => {
  const out: DiagramElement[] = [];
  for (let i = 0; i < 10; i++) out.push(i < mine ? B(20 + i * 28, y, 27, 24, '', RED) : B(20 + i * 28, y, 27, 24, '', GREEN));
  return out;
};
